    "earlyLifeEn": "Born into a Sherpa family of yak herders in the shadow of Mount Everest, originally named Namgyal Wangdi. A high lama of Rongbuk Monastery advised his parents to rename him Tenzing Norgay ('wealthy fortunate follower of religion').",
    "earlyLifeMl": "എവറസ്റ്റിന്റെ താഴ്‌വരയിൽ ഒരു യാക്ക് കർഷക കുടുംബത്തിലാണ് ജനനം. നംഗ്യാൽ വാങ്ദി എന്നായിരുന്നു ആദ്യ പേര്. പിന്നീട് റോങ്ബുക് ആശ്രമത്തിലെ ലാമയാണ് ടെൻസിങ് നോർഗെ എന്ന പേര് നൽകിയത്.",
    "educationEn": "Self-educated in the harsh Himalayas; master of seven Himalayan languages; later trained generations at Himalayan Mountaineering Institute (HMI).",
    "educationMl": "ഹിമാലയൻ ഗ്രാമങ്ങളിൽ പ്രകൃതിയോട് പൊരുതി ജീവിച്ച അനുഭവജ്ഞാനം. ഏഴോളം ഭാഷകൾ സ്വായത്തമാക്കി. പിന്നീട് ഹിമാലയൻ മൗണ്ടനീയറിംഗ് ഇൻസ്റ്റിറ്റ്യൂട്ടിന്റെ ഡയറക്ടറായി.",
    "journeyEn": "Moved to Darjeeling at age 19. Joined his first Everest expedition in 1935 as a 20-year-old porter under Eric Shipton. Participated in six unsuccessful Everest expeditions. In 1952, reached 8,595m with Swiss climber Raymond Lambert, paving the route used in 1953.",
    "journeyMl": "19-ാം വയസ്സിൽ ഡാർജിലിംഗിലേക്ക് മാറി. 1935-ൽ എറിക് ഷിപ്റ്റന്റെ ദൗത്യത്തിൽ പോർട്ടറായി തുടങ്ങിയ യാത്ര. 1952-ൽ സ്വിസ് ടീമിനൊപ്പം 8,595 മീറ്റർ വരെ എത്തി.",
    "majorExpeditionsEn": [
      "1935, 1936, 1938 British Mount Everest Expeditions.",
      "1952 Swiss Mount Everest Expedition (reached 8,595m with Raymond Lambert).",
      "1953 British Mount Everest Expedition (Historic Summit push with John Hunt & Edmund Hillary)."
    ],
    "majorExpeditionsMl": [
      "1935, 1936, 1938 ബ്രിട്ടീഷ് എവറസ്റ്റ് പര്യവേഷണങ്ങൾ.",
      "1952 സ്വിസ് എവറസ്റ്റ് ദൗത്യം.",
      "1953 ബ്രിട്ടീഷ് എവറസ്റ്റ് പര്യവേഷണം (ചരിത്ര വിജയം)."
    ],
    "historicAchievementsEn": [
      "First human to stand atop Mount Everest (8,848.86m) on May 29, 1953, at 11:30 AM.",
      "Founding Director of Field Training at the Himalayan Mountaineering Institute (HMI), Darjeeling.",
      "Named one of Time Magazine's 100 Most Influential People of the 20th Century."
    ],
    "historicAchievementsMl": [
      "1953 മെയ് 29-ന് എവറസ്റ്റിന്റെ നെറുകയിലെത്തിയ ആദ്യ മനുഷ്യരിൽ ഒരാൾ.",
      "ഡാർജിലിംഗ് എച്ച്.എം.ഐയുടെ സ്ഥാപക ഫീൽഡ് ഡയറക്ടർ.",
      "ടൈം മാഗസിന്റെ ഇരുപതാം നൂറ്റാണ്ടിലെ ഏറ്റവും സ്വാധീനമുള്ള 100 വ്യക്തികളിൽ ഒരാൾ."
    ],
    "awardsEn": [
      "George Medal (UK, 1953)",
      "Padma Bhushan (India, 1959)",
      "Order of the Star of Nepal (1953)"
    ],
    "awardsMl": [
      "ജോർജ്ജ് മെഡൽ (ബ്രിട്ടൻ, 1953)",
      "പദ്മഭൂഷൺ (ഇന്ത്യ, 1959)",
      "ഓർഡർ ഓഫ് ദ സ്റ്റാർ ഓഫ് നേപ്പാൾ (1953)"
    ],
    "challengesEn": "Faced extreme poverty in early youth, survived deadly blizzards, lost several children to childhood illnesses, and weathered toxic political disputes over whether he or Hillary stepped on the summit first.",
    "challengesMl": "കുട്ടിക്കാലത്തെ കൊടിയ ദാരിദ്ര്യം, കൊടും ശൈത്യം, മക്കളുടെ വിയോഗം എന്നിവ അതിജീവിച്ചു. വിജയത്തിന് ശേഷം ആരാണ് ആദ്യം കാലുകുത്തിയത് എന്ന രാഷ്ട്രീയ വിവാദങ്ങളിൽ സമചിത്തതയോടെ നിലകൊണ്ടു.",
    "contributionsEn": "Transformed global perception of the Sherpa community from subordinate mountain porters to world-class mountaineering equals. Established professional alpine training standards across India.",
    "contributionsMl": "ഷെർപ്പകളെ വെറും ചുമട്ടുകാരായി കണ്ടിരുന്ന ലോകത്തിന് മുന്നിൽ അവരെ തുല്യരും കരുത്തരുമായ പർവ്വത നായകന്മാരായി പ്രതിഷ്ഠിച്ചു.",
    "interestingFactsEn": [
      "Buried chocolate, biscuits, and a blue-and-red pencil given by his daughter Nima as a summit offering to the Buddhist spirits of Chomolungma.",
      "Never knew his exact birth date, so he chose May 29 (the day of his Everest summit) as his official birthday.",
      "Refused to sign commercial endorsements that exploited his Sherpa heritage."
    ],
    "interestingFactsMl": [
      "എവറസ്റ്റ് കീഴടക്കിയ ശേഷം മകൾ നൽകിയ പെൻസിലും ചോക്ലേറ്റും പ്രാർത്ഥനയോടെ മഞ്ഞിൽ സമർപ്പിച്ചു.",
      "ജനിച്ച തീയതി കൃത്യമായി അറിയാത്തതിനാൽ എവറസ്റ്റ് കീഴടക്കിയ മെയ് 29 സ്വന്തം ജന്മദിനമായി തിരഞ്ഞെടുത്തു."
    ],
