    "fullNameMl": "റെയിൻഹോൾഡ് മെസ്നർ",
    "portrait": "images/discover/mountaineers/reinhold-messner.jpg",
    "nationalityEn": "Italian (South Tyrolean)",
    "nationalityMl": "ഇറ്റാലിയൻ",
    "birthplaceEn": "Brixen, South Tyrol, Italy (Born September 17, 1944)",
    "birthplaceMl": "ബ്രിക്സൻ, ഇറ്റലി (ജനനം: 1944 സെപ്റ്റംബർ 17)",
    "shortBioEn": "The undisputed purist of high-altitude alpinism who became the first person to climb all 14 eight-thousanders, the first to climb Everest solo, and the first to summit Everest without supplemental oxygen.",
    "shortBioMl": "ഓക്സിജൻ സിലിണ്ടറുകളില്ലാതെ എവറസ്റ്റ് കൊടുമുടി ഒറ്റയ്ക്ക് കീഴടക്കുകയും ലോകത്തിലെ 14 എണ്ണായിരം മീറ്റർ കൊടുമുടികളും പൂർത്തിയാക്കുകയും ചെയ്ത ഇതിഹാസ പർവ്വതാരോഹകൻ.",
    "keyAchievementEn": "First to climb all 14 8,000m peaks (1970–1986); First solo ascent of Everest without supplemental oxygen (1980).",
    "keyAchievementMl": "14 എണ്ണായിരം മീറ്റർ കൊടുമുടികളും കീഴടക്കിയ ആദ്യ വ്യക്തി (1970–1986); ഓക്സിജൻ ഇല്ലാതെ എവറസ്റ്റ് ഒറ്റയ്ക്ക് കീഴടക്കിയ ആദ്യ മനുഷ്യൻ (1980).",
    "earlyLifeEn": "Raised in the Villnöß Valley in the Italian Dolomites alongside eight siblings. His father introduced him to rock climbing on the towering limestone spires of the Dolomites at the age of five.",
    "earlyLifeMl": "ഇറ്റലിയിലെ ഡോലോമൈറ്റ്സ് മലനിരകളിലാണ് ജനിച്ചു വളർന്നത്. അഞ്ചാം വയസ്സിൽ പിതാവിനൊപ്പം പാറക്കെട്ടുകൾ കയറിത്തുടങ്ങി.",
    "educationEn": "Studied architectural engineering at the University of Padua before dedicating his career to professional mountaineering and philosophy.",
    "educationMl": "പാദുവ സർവകലാശാലയിൽ ആർക്കിടെക്ചറൽ എഞ്ചിനീയറിംഗ് പഠിച്ചു.",
    "journeyEn": "Pioneered lightweight 'Alpine Style' climbing: zero supplemental oxygen, no fixed camps, no porter chains. Climbed Nanga Parbat via the Rupal Face in 1970 with brother Günther. In 1978, shattered medical orthodoxy by summiting Everest with Peter Habeler without oxygen, followed by his solo 1980 monsoon ascent.",
    "journeyMl": "ഭാരമേറിയ ഉപകരണങ്ങളും സ്ഥിരമായ കയറുകളും ഒഴിവാക്കി കുറഞ്ഞ ഭാരവുമായി മലകയറുന്ന 'ആൽപൈൻ ശൈലി' ലോകത്തിന് പരിചയപ്പെടുത്തി. 1978-ൽ ഓക്സിജൻ സിലിണ്ടറില്ലാതെ എവറസ്റ്റ് കീഴടക്കി ശാസ്ത്ര ലോകത്തെ അത്ഭുതപ്പെടുത്തി.",
    "majorExpeditionsEn": [
      "1970 Nanga Parbat (Rupal Face First Ascent).",
      "1978 Mount Everest (First ascent without supplemental oxygen with Peter Habeler).",
      "1980 Mount Everest Solo Ascent (Monsoon season, completely solo, zero oxygen).",
      "1986 Lhotse (Completed the 14th 8,000er)."
    ],
    "majorExpeditionsMl": [
      "1970 നംഗ പർവ്വത് (റൂപൽ ഫേസ് വഴി).",
      "1978 എവറസ്റ്റ് (ഓക്സിജൻ ഇല്ലാതെ ആദ്യ വിജയം).",
      "1980 എവറസ്റ്റ് സോളോ അസെന്റ് (ഒറ്റയ്ക്ക്, മഴക്കാലത്ത്).",
      "1986 ലോത്സെ (14 കൊടുമുടികൾ പൂർത്തിയാക്കി)."
    ],
    "historicAchievementsEn": [
      "First human in history to summit all 14 eight-thousanders (1970–1986).",
      "First human to climb Everest completely solo during monsoon season (1980).",
      "First to cross Antarctica on skis with Arved Fuchs (1989–1990, 2,800 km).",
      "Formulated the 'Messner List' of the Seven Summits (incorporating Carstensz Pyramid)."
    ],
    "historicAchievementsMl": [
      "14 എണ്ണായിരം മീറ്റർ കൊടുമുടികളും പൂർത്തിയാക്കിയ ലോകത്തിലെ ആദ്യ വ്യക്തി.",
      "എവറസ്റ്റ് പൂർണ്ണമായും ഒറ്റയ്ക്ക് കീഴടക്കിയ ആദ്യ പർവ്വതാരോഹകൻ.",
      "അന്റാർട്ടിക്കയിലൂടെ 2,800 കി.മീ സ്കീയിംഗ് നടത്തി ആദ്യമായി കുറുകെ കടന്നു.",
      "സെവൻ സമ്മിറ്റ്സിലെ മെസ്നർ ലിസ്റ്റ് നിർദ്ദേശിച്ചു."
    ],
    "awardsEn": [
      "Piolet d'Or Lifetime Achievement Award (2010)",
      "Patron's Medal of the Royal Geographical Society (2001)",
      "Princess of Asturias Award for Sports (2018)"
    ],
    "awardsMl": [
      "പിയോലെ ഡി ഓർ ലൈഫ് ടൈം അച്ചീവ്മെന്റ് അവാർഡ് (2010)",
      "റോയൽ ജിയോഗ്രഫിക്കൽ സൊസൈറ്റി അവാർഡ്",
      "പ്രിൻസസ് ഓഫ് അസ്റ്റൂറിയാസ് സ്പോർട്സ് അവാർഡ്"
    ],
    "challengesEn": "Lost seven toes and several fingertips to severe frostbite during the 1970 Nanga Parbat descent, where his beloved brother Günther was tragically swept away and killed by an avalanche.",
    "challengesMl": "1970-ൽ നംഗ പർവ്വതത്തിൽ വെച്ച് സഹോദരൻ ഗുന്തറിനെ ഹിമപാതത്തിൽ നഷ്ടമായി. കൊടും തണുപ്പിൽ ഏഴ് കാൽവിരലുകളും വിരൽത്തുമ്പുകളും മുറിച്ചുമാറ്റേണ്ടി വന്നു.",
    "contributionsEn": "Founded the Messner Mountain Museum (MMM) network consisting of six museums across the Alps, educating humanity on mountain culture, glaciology, and environmental preservation.",
    "contributionsMl": "ആൽപ്സ് പർവ്വതനിരകളിൽ ആറ് മെസ്നർ മൗണ്ടൻ മ്യൂസിയങ്ങൾ സ്ഥാപിച്ചു. പരിസ്ഥിതി സംരക്ഷണത്തിനായി ശക്തമായി വാദിക്കുന്നു.",
    "interestingFactsEn": [
      "Served as a Member of the European Parliament for the Italian Green Party from 1999 to 2004.",
      "Author of more than 80 books on mountaineering philosophy and high-altitude exploration.",
      "Walked 2,000 km across the Gobi Desert solo at age 60."
    ],
    "interestingFactsMl": [
      "1999 മുതൽ 2004 വരെ യൂറോപ്യൻ പാർലമെന്റിൽ അംഗമായിരുന്നു.",
      "80-ലധികം പുസ്തകങ്ങൾ രചിച്ചു.",
      "60-ാം വയസ്സിൽ ഗോബി മരുഭൂമിയിലൂടെ ഒറ്റയ്ക്ക് 2,000 കി.മീ നടന്നു."
    ],
