      "ടാറ്റാ സ്റ്റീൽ അഡ്വഞ്ചർ ഫൗണ്ടേഷന്റെ മേധാവിയായി 3 പതിറ്റാണ്ട് സേവനമനുഷ്ഠിച്ചു.",
