      "എവറസ്റ്റിന്റെ നെറുകയിൽ ദുർഗ്ഗാദേവിയുടെ ചെറിയ വിഗ്രഹവും ഹനുമാൻ ചാലിസയും വെച്ച് പ്രാർത്ഥിച്ചു."
