      "ഒരാഴ്ചയ്ക്കുള്ളിൽ രണ്ട് തവണ എവറസ്റ്റ് കയറിയ റെക്കോർഡ്.",
      "ഖുംബു ഐസ്ഫാളിലൂടെ ലോകമെമ്പാടുമുള്ള യാത്രികർക്കായി വഴിയൊരുക്കുന്ന പ്രധാന ഗൈഡ്."
