      "1663: ഡച്ചുകാർ കൊട്ടാരം പുനരുദ്ധരിച്ചു.",
      "1951: കേന്ദ്ര പുരാവസ്തു വകുപ്പ് സംരക്ഷിത സ്മാരകമായി പ്രഖ്യാപിച്ചു."
