      "50,000 സൈനികർക്ക് നാല് വർഷം കുടിക്കാൻ ആവശ്യമായ വെള്ളം സംഭരിക്കുന്ന 84 ജലാശയങ്ങൾ കോട്ടയ്ക്കുള്ളിൽ ഉണ്ടായിരുന്നു.",
