    "ancientHistoryEn": "Inhabited by nomadic hunter tribes known as the Rakshasas before being integrated into the early Vedic Kullu kingdom (Kulanthapitha – 'The End of the Habitable World'). Key junction on the ancient trade route to Ladakh and Tibet over Rohtang Pass.",
