      "1903: കൽക്ക-ഷിംല ടോയ് ട്രെയിൻ ഉദ്ഘാടനം ചെയ്തു.",
      "1945: ഇന്ത്യൻ സ്വാതന്ത്ര്യ ചർച്ചകൾക്കായി ഷിംല കോൺഫറൻസ് ചേർന്നു.",
      "1972: ഇന്ദിരാഗാന്ധിയും സുൾഫിക്കർ അലി ഭൂട്ടോയും ചേർന്ന് ചരിത്രപ്രസിദ്ധമായ ഷിംല കരാർ ഒപ്പുവെച്ചു."
