    "tourismDevelopmentEn": "World-renowned international spiritual and trekking hub, famous for Buddhist teachings, meditation retreats, and the Triund ridge hike.",
    "tourismDevelopmentMl": "ആത്മീയ പഠനങ്ങളുടെയും ട്രെക്കിംഗിന്റെയും അന്താരാഷ്ട്ര കേന്ദ്രം.",
    "referencesEn": "Central Tibetan Administration Records; Dalai Lama's 'Freedom in Exile'; ASI Kangra."
