    "architectureEn": "Fortress-monastery (Khangtsen) architecture perched atop jagged vertical mud cliffs, built using thick rammed earth, unbaked sun-dried mud bricks, and wooden timber frameworks designed to retain thermal warmth in -30°C winters.",
